    int digitCount = 0;
    while (absValue > 0) {
        sb.append(absValue % 10);
        absValue /= 10;
        digitCount++;
        if (absValue > 0 && digitCount % 3 == 0) {
            sb.append('.');
        }
    }
    if (negative) {
        sb.append('-');
    }
    return sb.reverse().toString();
